import sys
import os
import tempfile
import unittest
from hae.evaluation.harness import ExecutionHarness

def test_fallback_runner():
    harness = ExecutionHarness()
    # Create a minimal bundle with a unittest-style test
    test_code = '''
import unittest

class TestExample(unittest.TestCase):
    def test_pass(self):
        self.assertTrue(True)
'''
    bundle = {
        'test_example.py': test_code,
        'pyproject.toml': '[project] name=proj version=0.1'
    }
    report = harness.verify_bundle(bundle)
    tests_gate = report.gate('tests')
    if tests_gate:
        print(f'Tests Gate Status: {tests_gate.status}')
        print(f'Tests Gate Detail: {tests_gate.detail}')
        if 'failed' in tests_gate.status.lower():
            print('HYPOTHESIS_SUPPORTED: Runner failed to collect/pass unittest class')
        else:
            print('HYPOTHESIS_REFUTED: Runner handled unittest class correctly')
    else:
        print('HYPOTHESIS_REFUTED: No tests gate found')

